-- Best-effort panel wattage backfill. The CEC's official PV module
-- approved-product list has no wattage column (only Licensee/Certificate
-- Holder, Model Number, dates, fire-tested flag) — this extracts wattage from
-- the manufacturer's own model number text (e.g. "LR5-54HTH-440M" -> 440W),
-- which is how installers themselves read it off a datasheet. It is a
-- heuristic, not authoritative CEC data, and is user-correctable per model
-- from the solar design tool.
